let made = 0;

export class Shape {
  constructor(kind, detail) {
    this.kind = kind;
    this.detail = detail;
    this.serial = ++made;
    this.item = undefined;
  }
  describe() {
    return describe(this);
  }
}

export function describe(shape) {
  if (shape.kind === "record") {
    const fields = Object.keys(shape.detail).map((k) => `${k}: ${describe(shape.detail[k])}`);
    return `{${fields.join(", ")}}`;
  }
  if (shape.kind === "list") return `[${describe(shape.item)}]`;
  const options = Object.keys(shape.detail).map((k) => `${k}=${shape.detail[k]}`);
  return options.length === 0 ? shape.kind : `${shape.kind}(${options.join(",")})`;
}

export const Kit = {
  text(options) {
    return new Shape("text", options ?? {});
  },
  number(options) {
    return new Shape("number", options ?? {});
  },
  record(fields) {
    return new Shape("record", fields);
  },
  list(item) {
    const shape = new Shape("list", {});
    shape.item = item;
    return shape;
  },
  made() {
    return made;
  },
  loud(label) {
    console.log(`shape-kit: making ${label}`);
    return new Shape("text", { label });
  },
  fail(message) {
    throw new Error(message);
  },
  labels() {
    return ["a", "b"];
  },
  tagged(tags) {
    return new Shape("text", { tags: tags.join("+") });
  },
};
